PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(user_id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','port_officer','auditor','viewer')), is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ports(port_id INTEGER PRIMARY KEY, port_name TEXT NOT NULL, country TEXT NOT NULL, region TEXT, code TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS vessels(vessel_id INTEGER PRIMARY KEY, vessel_name TEXT NOT NULL, vessel_identifier TEXT UNIQUE, flag_country TEXT);
CREATE TABLE IF NOT EXISTS cargo_records(cargo_id INTEGER PRIMARY KEY, cargo_reference TEXT UNIQUE NOT NULL, description TEXT NOT NULL, cargo_type TEXT, quantity REAL NOT NULL CHECK(quantity>=0), unit_of_measure TEXT DEFAULT 'units', origin_port_id INTEGER REFERENCES ports(port_id) ON DELETE SET NULL, destination_port_id INTEGER REFERENCES ports(port_id) ON DELETE SET NULL, vessel_id INTEGER REFERENCES vessels(vessel_id) ON DELETE SET NULL, recorded_by INTEGER NOT NULL REFERENCES users(user_id), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, current_status TEXT NOT NULL DEFAULT 'recorded' CHECK(current_status IN ('recorded','inspected','in_transit','at_port','delivered','on_hold')), notes TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cargo_events(event_id INTEGER PRIMARY KEY, cargo_id INTEGER NOT NULL REFERENCES cargo_records(cargo_id) ON DELETE CASCADE, port_id INTEGER REFERENCES ports(port_id) ON DELETE SET NULL, event_type TEXT NOT NULL, event_time TEXT DEFAULT CURRENT_TIMESTAMP, details TEXT, recorded_by INTEGER NOT NULL REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS audit_logs(audit_id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(user_id) ON DELETE SET NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cargo_status ON cargo_records(current_status);
CREATE INDEX IF NOT EXISTS idx_cargo_ref ON cargo_records(cargo_reference);
CREATE INDEX IF NOT EXISTS idx_event_cargo ON cargo_events(cargo_id);
